pub(crate) fn is_a_variant(declared: &collections::BTreeSet<String>, callee: &str) -> bool {
    let mut parts: Vec<String> = nikaia_std::block::list(nikaia_std::block::Place::Block);
    for part in callee.split("::") { parts.push(nikaia_std::block::Text::from(part.to_string())); }
    if parts.len() < 2 || *unsafe { nikaia_std::proven::read(&parts, (nikaia_std::proven::sub::<i64>(parts.len() as i64, 1)) as usize) } == "new" { return false; }
    declared.contains(&struct_type(callee))
}

pub(crate) fn published(own: &Ledger, field: &str) -> bool {
    let c: Vec<scalar> = nikaia_std::list::scalars(field.chars());
    let dot = find_text(&c, 0, ".");
    if dot < 0 { return false; }
    let owner = slice(&c, 0, dot);
    let name = slice(&c, dot + 1, c.len() as i64);
    let contract = match *nikaia_std::index::get(&own.types, &owner) { Some(__nikaia_value) => __nikaia_value, None => return false };
    if !contract.public { return false; }
    for one in contract.fields.iter() { if one.name == name && one.public { return true; } }
    false
}

